[
  {
    "incident": {
      "component": "loki-storage-pvc",
      "category": "resource_exhaustion",
      "status": "firing",
      "summary": "PersistentVolumeClaim data-loki-0 in namespace logging is 92% full and approaching capacity."
    },
    "assessment": {
      "urgency": "high",
      "rationale": "The volume is at 92% capacity with a growth rate of 0.5GiB/h, meaning it will be completely full in approximately 16 hours, which will cause Loki to stop ingesting logs."
    },
    "facts": [
      "Alert name: KubePersistentVolumeFillingUp",
      "Namespace: logging",
      "PVC: data-loki-0",
      "Severity: warning",
      "Environment: prod",
      "Current usage: 92%",
      "Filesystem size: 100GiB",
      "Available space: 8GiB",
      "Growth rate: 0.5GiB/h",
      "Storage class: local-path",
      "allow_volume_expansion: false",
      "reclaim_policy: Delete"
    ],
    "missing_context": [
      {
        "item": "Loki retention policy",
        "why": "To determine if automatic cleanup can resolve the issue",
        "how_to_check": "Check Loki configuration (ConfigMap) for 'retention_period'"
      },
      {
        "item": "Current log ingestion volume",
        "why": "To see if a sudden spike caused this or if it is steady growth",
        "how_to_check": "Prometheus query: rate(loki_ingester_bytes_received_total[1h])"
      }
    ],
    "immediate_actions": [
      {
        "action": "Check Loki retention settings",
        "purpose": "Reduce storage usage by deleting old logs",
        "conditions": "If retention is set too high or not at all",
        "expected_effect": "Freeing up disk space automatically",
        "risks": "Loss of historical log data",
        "requires_approval": true,
        "verify": "Check available space via kubectl exec or node filesystem check",
        "rule_ids": [
          "RETENTION_POLICY_CHECK"
        ]
      },
      {
        "action": "Manual cleanup of old chunks/indexes",
        "purpose": "Immediate emergency space recovery",
        "conditions": "If retention policy adjustment is too slow",
        "expected_effect": "Immediate increase in available bytes",
        "risks": "Potential corruption of Loki index if files are deleted while in use",
        "requires_approval": true,
        "verify": "df -h on the host/pod",
        "rule_ids": [
          "MANUAL_CLEANUP"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Inspect PVC usage trends",
        "hypothesis": "The growth rate is accelerating",
        "how_to_check": "Prometheus query: predict_linear(kubelet_volume_stats_available_bytes{persistentvolumeclaim='data-loki-0'}[1h], 3600)"
      },
      {
        "step": "Check for log spikes",
        "hypothesis": "A specific service is flooding the logs",
        "how_to_check": "Loki query: count_over_time({namespace='logging'}[1h])"
      }
    ],
    "root_cause_hypotheses": [
      "Loki retention policy is insufficient for current ingestion rates",
      "Unexpected spike in log volume from a specific application",
      "Storage class 'local-path' prevents easy online volume expansion"
    ],
    "dangerous_operations": [
      {
        "operation": "Manual deletion of files in /data/loki",
        "why_dangerous": "Can lead to index/chunk mismatch and Loki service failure",
        "rule_id": "DATA_INTEGRITY_RISK"
      },
      {
        "operation": "Changing storage class/moving data",
        "why_dangerous": "Local-path storage is tied to a specific node; moving data requires manual migration",
        "rule_id": "LOCAL_STORAGE_MIGRATION_RISK"
      }
    ],
    "applied_expert_rules": [
      "STORAGE_EXHAUSTION_PROTOCOL",
      "LOGGING_INFRA_MAINTENANCE"
    ],
    "incident_update": "🚨 *Alert: Loki Storage Filling Up* \nPVC `data-loki-0` in `logging` is at 92% (8GiB left). At current growth (0.5GiB/h), we have ~16h before exhaustion. Investigating retention policies and ingestion spikes. @oncall"
  }
]
